INSERT INTO flashcards(set_id,term,definition,ipa,part_of_speech,cefr,example_en,example_vi,notes,card_type,topic,subtopic,toeic_part,difficulty,pattern,collocations,word_family,explanation,audio_text,tags,source) SELECT @yl_v4_set_id,t.term,t.definition,t.ipa,t.part_of_speech,t.cefr,t.example_en,t.example_vi,t.notes,t.card_type,t.topic,t.subtopic,t.toeic_part,t.difficulty,t.pattern,t.collocations,t.word_family,t.explanation,t.audio_text,t.tags,t.source FROM tmp_yanglingo_toeic_v4 t WHERE @yl_v4_set_id IS NOT NULL AND @yl_v4_user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM flashcard_sets es JOIN flashcards ef ON ef.set_id=es.id WHERE es.user_id=@yl_v4_user_id AND LOWER(TRIM(ef.term))=LOWER(TRIM(t.term)));
