-- YangLingo TOEIC Vocabulary Expansion v4

-- Additive, user-scoped and duplicate-aware. Never deletes existing cards or SRS progress.
-- Public-source template: skip personal inserts when the example learner does not exist.
-- This sanitized migration is for fresh installs, not an overlay on an existing database.

SET @yl_v4_user_id := (SELECT id FROM users WHERE LOWER(email)=LOWER('learner@example.test') LIMIT 1);


SET @yl_v4_set_id := (SELECT id FROM flashcard_sets WHERE user_id=@yl_v4_user_id AND source_type='toeic_expansion_v4' ORDER BY id LIMIT 1);

CREATE TEMPORARY TABLE tmp_yanglingo_toeic_v4 (term VARCHAR(255) NOT NULL, definition TEXT NOT NULL, ipa VARCHAR(255) NOT NULL, part_of_speech VARCHAR(80) NOT NULL, cefr VARCHAR(8) NOT NULL, example_en TEXT NOT NULL, example_vi TEXT NOT NULL, notes TEXT NOT NULL, card_type VARCHAR(32) NOT NULL, topic VARCHAR(120) NULL, subtopic VARCHAR(120) NULL, toeic_part TINYINT UNSIGNED NULL, difficulty TINYINT UNSIGNED NOT NULL, pattern TEXT NULL, collocations TEXT NULL, word_family TEXT NULL, explanation TEXT NULL, audio_text TEXT NULL, tags VARCHAR(500) NULL, source VARCHAR(120) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;











DROP TEMPORARY TABLE IF EXISTS tmp_yanglingo_toeic_v4;

UPDATE flashcard_sets SET description=CONCAT('YangLingo v4 TOEIC expansion. Auto-seeded ', (SELECT COUNT(*) FROM flashcards WHERE set_id=@yl_v4_set_id), ' non-duplicate learning items for this account.') WHERE id=@yl_v4_set_id;
